const copy={fa:{eyebrow:'آرشیو دلار آمریکا · بازار آزاد',title:'قیمت سالانه دلار در ایران',subtitle:'کمترین و بیشترین قیمت ثبت‌شده برای یک دلار، به تومان.',sortLabel:'مرتب‌سازی:',year:'سال',minimum:'کمترین قیمت',maximum:'بیشترین قیمت',yearHeading:'سال شمسی',minHeading:'کمترین · تومان',maxHeading:'بیشترین · تومان',note:'— یعنی حداقل و حداکثر قابل تعیین نیست؛ سال‌های ابتدایی تنها یک دادهٔ سالانه دارند. سایر اعداد بر اساس مشاهدات موجود هستند و پوشش داده‌ها در همهٔ سال‌ها کامل نیست.',sourceLabel:'منبع داده:',asc:'صعودی ↑',desc:'نزولی ↓',light:'تم روشن',dark:'تم تاریک',loading:'در حال دریافت داده‌ها…',error:'دریافت داده‌ها ناموفق بود. لطفاً صفحه را دوباره بارگذاری کنید.',coverage:'آخرین داده:',updated:'دریافت آرشیو:'},en:{eyebrow:'US DOLLAR ARCHIVE · OPEN MARKET',title:'Yearly dollar prices in Iran',subtitle:'Lowest and highest recorded prices for one US dollar, in toman.',sortLabel:'Sort by:',year:'Year',minimum:'Minimum price',maximum:'Maximum price',yearHeading:'Persian year',minHeading:'Minimum · toman',maxHeading:'Maximum · toman',note:'— means extrema are unavailable: early years have only one annual observation. Other values reflect available observations; coverage is incomplete and varies by year.',sourceLabel:'Data source:',asc:'Ascending ↑',desc:'Descending ↓',light:'Light theme',dark:'Dark theme',loading:'Loading data…',error:'Could not load data. Please reload the page.',coverage:'Latest observation:',updated:'Archive retrieved:'}};
const $=id=>document.getElementById(id);
const read=key=>{try{return localStorage.getItem(key)}catch{return null}};
const save=(key,value)=>{try{localStorage.setItem(key,value)}catch{}};
let lang=read('language')==='en'?'en':'fa',theme=read('theme')||'light',ascending=false,data=null,failed=false;
function render(){const t=copy[lang];document.documentElement.lang=lang;document.documentElement.dir=lang==='fa'?'rtl':'ltr';document.documentElement.dataset.theme=theme;document.title=t.title;for(const id of ['eyebrow','title','subtitle','sortLabel','yearHeading','minHeading','maxHeading','note','sourceLabel'])$(id).textContent=t[id];$('language').textContent=lang==='fa'?'English':'فارسی';$('theme').textContent=t[theme==='dark'?'light':'dark'];$('theme').setAttribute('aria-pressed',String(theme==='dark'));$('direction').textContent=t[ascending?'asc':'desc'];for(const option of $('sort').options)option.textContent=t[option.value];$('status').textContent=failed?t.error:data?'':t.loading;if(!data)return;const locale=lang==='fa'?'fa-IR':'en-US',nf=new Intl.NumberFormat(locale);const date=value=>new Intl.DateTimeFormat(locale+'-u-ca-persian',{year:'numeric',month:'long',day:'numeric',timeZone:'UTC'}).format(new Date(value+'T12:00:00Z'));$('coverage').textContent=t.coverage+' '+date(data.latestDate);$('updated').textContent=t.updated+' '+date(data.retrievedAt);const key=$('sort').value;const sorted=[...data.years].sort((a,b)=>{if(a[key]===null&&b[key]!==null)return 1;if(b[key]===null&&a[key]!==null)return -1;return (ascending?1:-1)*((a[key]??0)-(b[key]??0))||b.year-a.year});$('rows').replaceChildren(...sorted.map(row=>{const tr=document.createElement('tr');for(const value of [row.year,row.minimum,row.maximum]){const td=document.createElement('td');td.textContent=value===null?'—':nf.format(value);tr.append(td)}return tr}));}
$('language').onclick=()=>{lang=lang==='fa'?'en':'fa';save('language',lang);render()};$('theme').onclick=()=>{theme=theme==='light'?'dark':'light';save('theme',theme);render()};$('sort').onchange=render;$('direction').onclick=()=>{ascending=!ascending;render()};render();fetch('data.json').then(r=>{if(!r.ok)throw Error(r.status);return r.json()}).then(value=>{data=value;render()}).catch(()=>{failed=true;render()});
